contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(this) && actor != address(c));
        bool ok;
        vm.prank(actor);
        try c.owned() { ok = true; } catch { ok = false; }
        // General rule: owned() succeeds iff the caller is the owner.
        assertTrue(ok == (actor == c.owner()));
    }
}

