// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));

        // owner starts at address(0); use it to hand ownership to a fuzzed actor
        vm.prank(address(0));
        c.transferOwnership(actor);

        // a successful owned() call must leave the owner untouched
        vm.prank(actor);
        c.owned();

        // general rule: after owned() runs, owner is still exactly the fuzzed actor
        assertTrue(c.owner() == actor);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        // Keep the domain wide: any non-zero address may become the owner.
        vm.assume(actor != address(0));

        // The deployer (this test contract) is the initial owner; hand
        // ownership to the fuzzed actor.
        c.transferOwnership(actor);

        // Drive c through `owned` as the fuzzed actor. As current owner,
        // the call succeeds; owned() is an empty body, so it must not
        // disturb the owner state set by transferOwnership.
        vm.prank(actor);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));

        // Universal rule: for every admissible actor, owned() succeeds for
        // the current owner and the owner remains exactly the address that
        // transferOwnership last installed.
        assertTrue(ok && c.owner() == actor);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        // Admissible domain: real addresses, caller distinct from the new owner so any
        // unauthorized mutation of the owner slot is immediately observable.
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(caller != newOwner);

        // Set a nonzero owner: the deployer-recorded owner (address(0)) performs the transfer.
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);

        // Drive the mutated entry point: only `caller` (a non-owner) attempts owned();
        // it must revert at onlyOwner and leave the owner untouched.
        vm.prank(caller);
        try c.owned() {
            // even a success must not alter the owner
        } catch {
            // expected for a non-owner
        }

        // General rule: owned() never changes the recorded owner.
        assertTrue(c.owner() == newOwner);
    }
}
